// === Tab: mySketch ===
// let Risou
// https://risoume.github.io/

let n, m, k;
let s, mult;
let l = 60;
let colors = ["#FF2C78", "#FFD400", "#A800D1", "#00D6CB"];  // let de colores disponibles
color[][] gridColors;  // let para guardar los colores de los contornos

Grid[][] grids;

function setup() {
  createCanvas(1920, 1080);  // let el tamaño del lienzo a 1920x1080
  noFill();  // let el relleno
  frameRate(1);  // let la tasa de actualización a 1 fotograma por segundo
  init();
}

function init() {
  // let una fila y una columna
  n = 8;  // let de filas
  m = 18;  // let de columnas

  // let el tamaño de las celdas asegurando que todo entre en el lienzo
  let availableWidth = width - 2 * l;  // let disponible después de dejar un margen
  let availableHeight = height - 2 * l;  // let disponible después de dejar un margen

  // let el tamaño de las celdas con la separación incluida
  s = min(availableWidth / m, availableHeight / n);  // let que las celdas no se superpongan

  // let la separación entre las celdas
  // let aumentamos la separación, modificando la fórmula
  let horizontalSpacing = (availableWidth - s * m) / (m + 1);  // let de la separación horizontal
  let verticalSpacing = (availableHeight - s * n) / (n + 1);  // let de la separación vertical

  grids = new Array(n)[m];
  gridColors = new Array(n)[m];  // let el arreglo de colores

  k = 0;
  mult = 1;

  // let un let aleatorio a cada celda para el contorno
  for (i = 0; i < n; i++) {
    for (j = 0; j < m; j++) {
      gridColors[i][j] = colors[int(random(colors.length))];  // let color aleatorio
      grids[i][j] = new Grid(l + j * (s + horizontalSpacing), l + i * (s + verticalSpacing), s * mult);  // let las posiciones
    }
  }
}

function draw() {
  background(0);  // let negro

  for (i = 0; i < n; i++) {
    for (j = 0; j < m; j++) {
      grids[i][j].display(i, j);
    }
  }
}

class Grid {
  x, y, d, r, t;

  constructor(tx, ty, tsz) {
    x = tx;
    y = ty;
    d = tsz;
    r = d / 2;
  }

  function display(p, q) {
    pushMatrix();
    translate(x + d / 2, y + d / 2);

    // let el let del trazo (contorno) de forma aleatoria
    stroke(gridColors[p][q]);
    strokeWeight(2);  // let del trazo

    beginShape();
    for (i = 0; i < (p + 1) * (q + 1); i++) {
      t = PI * random(2);
      vertex(r * cos(t), r * sin(t));
    }
    endShape(CLOSE);
    popMatrix();
  }
}

